import random
random.seed(74300)
times = [[i, i + 1, random.randint(50, 100)] for i in range(1, 2000)]
seen = {(i, i + 1) for i in range(1, 2000)}
while len(times) < 20000:
    u, v = random.randint(1, 2000), random.randint(1, 2000)
    if u != v and (u, v) not in seen:
        seen.add((u, v))
        times.append([u, v, random.randint(0, 100)])
